#!/bin/bash
# Checks the shipped Hyprland configuration with Hyprland itself (`Hyprland --verify-config`, no GPU needed).
# For Heiss Dark and Heiss Light: builds a throw-away home, runs heiss-first-login on it (so the file that is
# checked is the one a user really gets), adds a user include and verifies the result. Fails on any error, on a
# missing "config ok", and when the autogenerated-config marker shows up.
# Usage: scripts/check-hyprland-config.sh        (HYPRLAND_BIN overrides the binary; the version is printed)
set -u
REPO="$(cd "$(dirname "$0")/.." && pwd)"
BIN="${HYPRLAND_BIN:-Hyprland}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
chmod 700 "$tmp"

command -v "$BIN" >/dev/null 2>&1 || [ -x "$BIN" ] || { echo "FAIL: $BIN not found"; exit 2; }
echo "Hyprland: $("$BIN" --version 2>&1 | head -n 1)"

fail=0
for theme in dark light; do
  home="$tmp/$theme/home"
  src="$tmp/$theme/src"
  mkdir -p "$home" "$src/hypr" "$src/waybar" "$src/theme/dark"
  cp "$REPO"/desktop/hypr/* "$src/hypr/"
  cp "$REPO"/desktop/waybar/* "$src/waybar/"
  cp "$REPO/branding/tokens/generated/desktop/$theme/"* "$src/theme/dark/"   # first login always reads theme/dark
  env -i PATH="$PATH" HOME="$home" HEISS_DESKTOP_SRC="$src" XDG_CONFIG_HOME="$home/.config" \
      XDG_STATE_HOME="$home/.local/state" sh "$REPO/desktop/bin/heiss-first-login" || { echo "FAIL: first login ($theme)"; fail=1; continue; }
  conf="$home/.config/hypr/hyprland.lua"
  [ -s "$conf" ] || { echo "FAIL: first login did not create hyprland.lua ($theme)"; fail=1; continue; }
  grep -q '^hl\.config({ *autogenerated *= *true' "$conf" && { echo "FAIL: autogenerated marker in $conf ($theme)"; fail=1; }
  out="$tmp/$theme/out"
  env -i PATH="$PATH" HOME="$home" XDG_RUNTIME_DIR="$tmp" XDG_CONFIG_HOME="$home/.config" \
      LD_LIBRARY_PATH="${LD_LIBRARY_PATH:-}" "$BIN" --verify-config -c "$conf" > "$out" 2>&1
  rc=$?
  if [ "$rc" -ne 0 ] || ! grep -q '^config ok$' "$out"; then
    echo "FAIL: $theme (exit $rc)"; if grep -q 'Config parsing result' "$out"; then sed -n '/Config parsing result/,$p' "$out"; else cat "$out"; fi; fail=1
  else
    echo "OK: $theme"
  fi
done
exit "$fail"
